<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>ПрофиСпорт — управление</title><style>:root{--y:#f2c94c;--g:#343a40;--bg:#f5f5f3;--tx:#202124;--muted:#747a80;--line:#e3e3df;--green:#19964a}html,body{margin:0;width:100%;max-width:100%;overflow-x:hidden}*{box-sizing:border-box;min-width:0}body{font:15px/1.4 system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--tx);overflow-wrap:anywhere}button{font:inherit}.top{background:linear-gradient(135deg,#454b51,#2f3439);color:#fff;padding:15px max(18px,env(safe-area-inset-right)) 15px max(18px,env(safe-area-inset-left));position:sticky;top:0;z-index:20}.topin,main{width:100%;max-width:1040px;margin:auto}.topin{display:flex;align-items:center;justify-content:space-between}.brand{font-size:21px;font-weight:900}.brand i{font-style:normal;color:var(--y)}.logo{display:inline-grid;place-items:center;width:36px;height:36px;background:var(--y);color:#111;border-radius:9px;margin-right:9px}.menu{font-size:26px;color:#fff}.hero{height:145px;margin:18px 0;border-radius:20px;padding:24px;display:flex;flex-direction:column;justify-content:center;background:radial-gradient(circle at 82% 50%,#666 0,#3b4147 28%,#24292e 64%);color:#fff;overflow:hidden;position:relative}.hero:after{content:'◉';position:absolute;right:8%;font-size:120px;opacity:.12}.hero strong{font-size:25px;z-index:1}.hero strong i{font-style:normal;color:var(--y)}.hero span{font-size:16px;margin-top:5px;z-index:1}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.metric,.tile,.panel{background:#fff;border:1px solid var(--line);box-shadow:0 2px 10px #00000008}.metric{border-radius:16px;padding:14px}.metric small{color:var(--muted);display:block}.metric b{font-size:25px;display:block;margin:3px 0}.delta{font-size:12px;color:var(--green);font-weight:750}.title{margin:25px 0 12px;font-size:28px}.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.tile{border-radius:18px;padding:20px;min-height:142px;text-decoration:none;color:inherit;position:relative}.tile.primary{background:linear-gradient(145deg,#fff9df,#fff2b3);border-color:#efc943}.ico{display:grid;place-items:center;width:44px;height:44px;border-radius:13px;background:#f2f2ef;font-size:22px;margin-bottom:14px}.primary .ico{background:var(--y)}.tile b{display:block;font-size:18px}.tile span{display:block;color:var(--muted);margin-top:5px}.arrow{position:absolute;right:18px;bottom:16px;font-size:22px}.panel{border-radius:18px;padding:20px;margin:14px 0}.importRow{display:flex;gap:16px;align-items:center}.importIcon{display:grid;place-items:center;flex:0 0 52px;width:52px;height:52px;border-radius:50%;background:var(--y);font-size:26px}.importText{flex:1}.importText h3{margin:0 0 3px;font-size:20px}.muted{color:var(--muted)}button{border:0;border-radius:12px;padding:13px 18px;background:var(--y);color:#111;font-weight:850;cursor:pointer}.importBtn{margin-top:15px;width:100%}.msg{padding:11px 0 0;word-break:break-word}.ok{color:#23783a}.err{color:#b93429}.technical{margin-top:10px}.technical summary{cursor:pointer;color:var(--muted);font-weight:700}.technical .inner{padding-top:12px}.secondary{background:#e9e9e5;color:#111}.status{display:flex;align-items:center;gap:11px;background:#eaf8ee;color:#19763b}.statusDot{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#22ad58;color:#fff;font-weight:900}.productsWrap{max-width:100%;overflow-x:auto}.bottom{display:none}.hidden{display:none!important}@media(max-width:760px){main{padding:0 12px 92px}.hero{height:125px;margin:12px 0;padding:19px}.hero strong{font-size:22px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{padding:13px}.metric b{font-size:22px}.title{font-size:25px;margin-top:20px}.tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.tile{padding:16px;min-height:150px}.tile b{font-size:17px}.tile span{font-size:14px}.panel{padding:17px}.bottom{position:fixed;display:grid;grid-template-columns:repeat(4,1fr);left:0;right:0;bottom:0;z-index:30;background:#fff;border-top:1px solid var(--line);padding:8px max(8px,env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) max(8px,env(safe-area-inset-left));box-shadow:0 -4px 18px #0001}.bottom a{text-decoration:none;color:#4c5156;text-align:center;font-size:11px;font-weight:700;padding:6px 2px;border-radius:10px}.bottom a:first-child{background:#fff2a8;color:#111}.bottom b{display:block;font-size:20px;line-height:1.1;margin-bottom:3px}.importRow{align-items:flex-start}}@media(max-width:360px){.tiles{grid-template-columns:1fr}.metrics{gap:7px}.metric b{font-size:20px}}</style></head><body><header class="top"><div class="topin"><div class="brand"><span class="logo">⚙</span>Профи<i>Спорт</i></div><div class="menu">☰</div></div></header><main><section class="hero"><strong>Профи<i>Спорт</i></strong><span>Всё для активного отдыха</span></section><section class="metrics"><div class="metric"><small>Товаров</small><b id="statProducts">—</b><span class="delta">+0 сегодня</span></div><div class="metric"><small>Заказов</small><b id="statOrders">—</b><span class="delta">+0 сегодня</span></div><div class="metric"><small>Фотографий</small><b>19 137</b><span class="delta">в базе</span></div><div class="metric"><small>Категорий</small><b>277</b><span class="delta">актуально</span></div></section><h1 class="title">Управление магазином</h1><section class="tiles"><a class="tile primary" href="#catalog"><span class="ico">◫</span><b>Каталог из 1С</b><span>Импорт и обновление товаров</span><i class="arrow">→</i></a><a class="tile" href="#orders"><span class="ico">🛒</span><b>Заказы</b><span>Просмотр и обработка</span><i class="arrow">→</i></a><a class="tile" href="#products"><span class="ico">◇</span><b>Товары</b><span>Редактирование каталога</span><i class="arrow">→</i></a><a class="tile" href="#categories"><span class="ico">▣</span><b>Категории</b><span>Структура и привязки</span><i class="arrow">→</i></a><a class="tile" href="#photos"><span class="ico">▧</span><b>Фотографии</b><span>Загрузка и управление</span><i class="arrow">→</i></a><a class="tile" href="#stats"><span class="ico">▥</span><b>Статистика</b><span>Продажи и отчёты</span><i class="arrow">→</i></a></section><section class="panel" id="catalog"><div class="importRow"><span class="importIcon">↻</span><div class="importText"><h3>Обновить каталог из 1С</h3><div class="muted">Товары, категории и фотографии — одним запуском.</div></div></div><button class="importBtn" id="run1cImportBtn">Обновить каталог</button><div id="run1cImportMsg" class="msg"></div><details class="technical"><summary>Диагностика импорта</summary><div class="inner"><button id="refreshImports" class="secondary">Проверить файлы</button><div id="importFiles" class="muted">Пока не проверено</div><br><button id="analyzeImportBtn" class="secondary">Проверить связи фотографий</button><div id="analyzeImportMsg" class="msg muted"></div><div id="analyzeImportResult"></div></div></details></section><section class="panel status"><span class="statusDot">✓</span><div><b>Сайт работает штатно</b><div>Ошибок не обнаружено</div></div></section><section class="panel" id="products"><h2>Товары</h2><div id="products" class="productsWrap"></div></section></main><nav class="bottom"><a href="#"><b>⌂</b>Главная</a><a href="#products"><b>◇</b>Товары</a><a href="#orders"><b>🛒</b>Заказы</a><a href="#more"><b>☰</b>Ещё</a></nav><script src="app.js?v=12"></script><script src="analyze.js?v=1"></script><script src="import-run.js?v=4"></script></body></html>